import React, { useContext } from 'react'
import CertificateItem from './CertificateItem'
import MyContext from '../../context/MyContext'

const Certificate = () => {
    const { certificates } = useContext(MyContext)
    // console.log(certificates);

    return (
        <div className='container pt-5 px-0'>
            <div className="row">
                {
                    certificates && certificates.map((cert, index) => (
                        <CertificateItem key={index} certificateImgUrl={cert.Certificate_URL} title={cert.Certificate_Title} name={cert.Certificate_Name} />
                    )
                    )
                }
                {/* // <CertificateItem certificateImgUrl={img} /> */}
            </div>

        </div>
    )
}

export default Certificate
