import React, { useContext, useState } from 'react'
import myContext from '../context/MyContext';
import apiService from '../apiservice/apiService';
import emailjs from 'emailjs-com';

// import base64 from 'base-64';

const Contact = () => {

  const { urls, SetAlert, LoadingProgress } = useContext(myContext)
  const [inputs, setInputs] = useState({});
  const [errors, setErrors] = useState({}); // for validation messages
  const [isSending, setIsSending] = useState(false);

  let formInput = "form-control rounded-0 focus-ring focus-ring-light"

  // Form validation function
  const validate = () => {
    const newErrors = {};
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const nameRegex = /^[a-zA-Z ]{2,}$/;

    if (!inputs.Contact_Name || !nameRegex.test(inputs.Contact_Name)) {
      newErrors.Contact_Name = "Enter a valid name (letters only)";
    }

    if (!inputs.Contact_Email || !emailRegex.test(inputs.Contact_Email)) {
      newErrors.Contact_Email = "Enter a valid email";
    }

    if (!inputs.Contact_Subject) {
      newErrors.Contact_Subject = "Subject is required";
    }

    if (!inputs.Contact_Message) {
      newErrors.Contact_Message = "Message cannot be empty";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (event) => {
    const name = event.target.name;
    const value = event.target.value;
    setInputs(values => ({ ...values, [name]: value }))
    setErrors(errors => ({ ...errors, [name]: "" })); // clear error on change
  }

  const handleSubmit = async (event) => {
    event.preventDefault();

    // if (isSending) return;

    if (!validate()) return;
    setIsSending(true); // lock form submission
    LoadingProgress(20);

    try {
      // 1. Send to backend
      const response = await apiService.post('contact/', inputs)
      LoadingProgress(40);

      // 2. Send to your email using EmailJS
      const emailRes = await emailjs.send(
        process.env.REACT_APP_EMAIL_JS_SERVICE_ID,
        process.env.REACT_APP_CONTACT_US_TEMPLATE_ID,
        {
          Contact_Name: inputs.Contact_Name,
          Contact_Email: inputs.Contact_Email,
          Contact_Subject: inputs.Contact_Subject,
          Contact_Message: inputs.Contact_Message,
        },
        process.env.REACT_APP_EMAIL_JS_PUBLIC_KEY,
      );

      LoadingProgress(50)
      if (response.status === 201 && emailRes.status === 200) {
        setInputs({})
        LoadingProgress(80)
        SetAlert("success", "Message sent Successfully!", 3000, true)
      }

    } catch (error) {
      if (error.response.status === 404) {
        SetAlert("error", "Failed to Send", 3000, true)
      }
      if (error.response.status === 401) {
        SetAlert("error", "Technical Error!", 3000, true)
      }
      // console.log(error);
    }
    finally {
      setIsSending(false); // ✅ Reset button back to normal
      LoadingProgress(100);
    }
  };

  return (
    <div className='row mt-3' id="contactMng">
      <hr />

      {/* Contact Details Start */}
      <div className="col-lg-4">

        {/* Location Row Start*/}
        <div className="row py-4">
          <div className="col d-flex">
            <div className="contactIcon rounded-1">
              <i className='bi bi-geo-alt'></i>
            </div>
            <div>
              <span className='MyHead3'>Location:</span>
              <br />
              <a href={urls.Location.url} target='_blank' rel='noreferrer'>{urls.Location.title}</a>
            </div>
          </div>
        </div>
        {/* Location Row End */}

        {/* Email Row Start*/}
        <div className="row pb-4">
          <div className="col d-flex">
            <div className="contactIcon rounded-1">
              <i className='bi bi-envelope'></i>
            </div>
            <div>
              <span className='MyHead3'>Email Us At:</span>
              <br />
              <a href={urls.Email.url}>{urls.Email.title}</a>
            </div>
          </div>
        </div>
        {/* Email Row End */}

        {/* Call Row Start*/}
        <div className="row pb-5">
          <div className="col d-flex">
            <div className="contactIcon rounded-1">
              <i className='bi bi-phone'></i>
            </div>
            <div>
              <span className='MyHead3'>Call Us On:</span>
              <br />
              <a href={urls.Mobile.url}>{urls.Mobile.title}</a>
            </div>
          </div>
        </div>
        {/* Call Row End*/}

      </div>
      {/* Contact Details End */}


      <div className="col-lg-1"></div>

      {/* Contact Form Start */}
      <div className="col-lg-7 border-bottom border-2 border-light px-lg-5 px-md-4 px-3 py-4 bg-light">
        <form id="contactForm" className='txt3' onSubmit={handleSubmit}>
          <h2 className='py-2'>Send a Message</h2>
          <div className="row">
            <div className="col-md-6">
              <input
                type="text"
                name='Contact_Name'
                value={inputs.Contact_Name || ""}
                onChange={handleChange}
                className={`${formInput} ${errors.Contact_Name ? "is-invalid" : ""}`}
                placeholder="Your Name" required />

              <div className="text-danger">{errors.Contact_Name}</div>
            </div>

            <div className="col-md-6">
              <input
                type="email"
                name='Contact_Email'
                value={inputs.Contact_Email || ""}
                onChange={handleChange}
                className={`${formInput} ${errors.Contact_Email ? 'is-invalid' : ''} mt-md-0 mt-3`}
                placeholder="Your Email" required />
              <div className="text-danger">{errors.Contact_Email}</div>
            </div>
          </div>

          <div className="row">
            <div className="col-md-12">
              <input
                type="text"
                name='Contact_Subject'
                value={inputs.Contact_Subject || ""}
                onChange={handleChange}
                className={`${formInput} ${errors.Contact_Subject ? 'is-invalid' : ''}`}
                placeholder='Subject...' required />
              <div className="text-danger">{errors.Contact_Subject}</div>
            </div>
          </div>
          <div className="row">
            <div className="col-md-12">
              <textarea
                name='Contact_Message'
                value={inputs.Contact_Message || ""}
                onChange={handleChange}
                className={`${formInput} ${errors.Contact_Message ? 'is-invalid' : ''}`}
                rows="4"
                cols="50"
                placeholder='Message...' required></textarea>
              <div className="text-danger">{errors.Contact_Message}</div>
            </div>
          </div>
          <div className="row mt-3">
            <div className="col-md-12">
              {/* <input type="submit" className='btn rounded-0' value="Send Message" /> */}
              <input
                type="submit"
                className="btn rounded-0"
                value={isSending ? "SENDING..." : "Send Message"}
                disabled={isSending}
              />
            </div>
          </div>
        </form>
      </div>
      {/* Contact Form End */}
    </div>
  )
}

export default Contact
