import React, { useState } from 'react';
import { motion } from 'framer-motion';

const CertificateItem = ({ certificateImgUrl, title, name }) => {
    const [hovered, setHovered] = useState(false);

    return (
        <div
            id='CertificateItem'
            className="col-lg-4 col-md-6 my-lg-3 mb-3"
            data-aos="zoom-in"
            data-aos-duration="1500"
            onMouseEnter={() => setHovered(true)}
            onMouseLeave={() => setHovered(false)}
        >
            <div className="position-relative overflow-hidden border shadow shadow-sm" style={{ cursor: 'pointer' }}>

                {/* Image with blur + zoom */}
                <motion.img
                    src={certificateImgUrl}
                    alt="Certificate"
                    className=" w-100 object-fit-cover img-fluid"
                    animate={{ scale: hovered ? 1.05 : 1, filter: hovered ? 'blur(1px)' : 'blur(0px)' }}
                    transition={{ duration: 0.4 }}
                />

                {/* Overlay with icon */}
                <motion.div
                    className="position-absolute top-0 start-0 w-100 h-100 d-flex align-items-center justify-content-center bg-dark bg-opacity-75"
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: hovered ? 1 : 0, y: hovered ? 0 : 20 }}
                    transition={{ duration: 0.4 }}
                >
                    <div className='text-center text-light'>
                        <h2 className='txt3'>{name}</h2>
                        <h5 className='txt2'>{title}</h5>
                        <a href={certificateImgUrl} target="_blank" rel="noopener noreferrer">
                            <i className="bi bi-download fs-3"></i>
                        </a>
                    </div>
                </motion.div>
            </div>
        </div>
    );
};

export default CertificateItem;
